	if data is not None:	
		chartData = []
		colHdrs = system.dataset.getColumnHeaders(data)
		dictLine = {}

		for row in range(data.rowCount):
			category = data.getValueAt(row, 'Category')
			for col in range(1, data.getColumnCount()):
				shift = colHdrs[col]
				value = data.getValueAt(row, col)
				if value is None:
					bgColor = '#AAAAAA'	#grey
				elif value >= 95:
					bgColor = '#00FF00'	#green
				elif value >= 75: 
					bgColor = '#FF00FF'	#yellow
				else:
					bgColor = '#FF0000'	#red

				dictLine = {}
				dictLine.update({"value":value})
				dictLine.update({"categoryX": shift})
				dictLine.update({"categoryY": category})
				dictLine.update({"bgColor": bgColor})

				chartData.append(dictLine)			

#		system.perspective.print(str(chartData))

		datasources = {}
		dataName = 'data'
		datasources.update({dataName: chartData})				

		self.getChild("flxCntDisplay").getChild("flxCntTables").getChild("XYChart_Shift").props.dataSources = datasources

	return
